65	// NewHandler builds the public HTTP surface backed by s.
66	func NewHandler(s *store.Store) http.Handler {
67		mux := http.NewServeMux()
68	
69		mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
70			writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
71		})
72	
73		mux.HandleFunc("POST /v1/devices", func(w http.ResponseWriter, r *http.Request) {
74			handleRegisterDevice(s, w, r)
75		})
76		// Non-POST verbs on the exact collection path: the method-less pattern is
77		// less specific than POST above, so it only catches the rest and answers a
78		// JSON 404 instead of ServeMux's slash redirect.
79		mux.HandleFunc("/v1/devices", func(w http.ResponseWriter, _ *http.Request) {
80			writeError(w, http.StatusNotFound, "unknown device path")
81		})
82		mux.HandleFunc("/v1/sessions", func(w http.ResponseWriter, _ *http.Request) {
83			writeError(w, http.StatusNotFound, "unknown session path")
84		})
85		mux.HandleFunc("POST /v1/devices/{deviceId}/sessions", func(w http.ResponseWriter, r *http.Request) {
86			handleCreateSession(s, w, r)
87		})
88		mux.HandleFunc("DELETE /v1/devices/{deviceId}/sessions/{sessionId}", func(w http.ResponseWriter, r *http.Request) {
89			handleDeleteSession(s, w, r)
90		})
91		mux.HandleFunc("GET /v1/sessions/{sessionId}/documents/{documentId}/changes", func(w http.ResponseWriter, r *http.Request) {
92			handleSessionChanges(s, w, r)
93		})
94		// Any other path under the new namespaces is a JSON 404 rather than
95		// ServeMux's plain-text one: every failure of a new endpoint answers JSON.
96		// Exact method-patterns above take precedence over these subtree patterns.
97		mux.HandleFunc("/v1/devices/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
98			writeError(w, http.StatusNotFound, "unknown device/session path")
99		})
100		mux.HandleFunc("/v1/sessions/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
101			writeError(w, http.StatusNotFound, "unknown session path")
102		})
103	
104		mux.HandleFunc("POST /v1/documents/{documentID}/changes", func(w http.ResponseWriter, r *http.Request) {
105			handlePostChanges(s, w, r)
106		})
107		mux.HandleFunc("GET /v1/documents/{documentID}/changes", func(w http.ResponseWriter, r *http.Request) {
108			handleListChanges(s, w, r)
109		})
110		mux.HandleFunc("POST /v1/documents/{documentID}/merge", func(w http.ResponseWriter, r *http.Request) {
111			handleMergeChange(s, w, r)
112		})
113		mux.HandleFunc("POST /v1/documents/{documentID}/snapshots", func(w http.ResponseWriter, r *http.Request) {
114			handlePostSnapshot(s, w, r)
115		})
116		mux.HandleFunc("GET /v1/documents/{documentID}/snapshots/{cursor}", func(w http.ResponseWriter, r *http.Request) {
117			handleGetSnapshot(s, w, r)
118		})
119		mux.HandleFunc("POST /v1/documents/{documentID}/restore", func(w http.ResponseWriter, r *http.Request) {
120			handleRestore(s, w, r)
121		})
122	
123		// ServeMux treats any empty path segment (the doubled slash in
124		// /v1/documents//..., /v1/devices//sessions or
125		// /v1/sessions//documents/...) as an unclean path and answers with a 307
126		// HTML redirect (a 404 in a real client). The API contract is a 400 JSON
127		// error for an empty identifier, so intercept those paths before the mux
128		// sees them. A trailing slash empties the final id of the device/session
129		// routes and is rejected there for the same reason; the document routes
130		// keep their pre-existing ServeMux behavior.
131		return emptyIDGuard(mux)
132	}
133	
134	// emptyIDGuard rejects requests carrying an empty path identifier with a 400
135	// JSON error instead of letting ServeMux emit its HTML redirect or a
136	// plain-text 404.
137	//
138	// The document family keeps its original rule (an empty documentID, i.e. the
139	// prefix /v1/documents//); other odd paths there retain their old response so
140	// the pre-existing surface is unchanged. The new device/session families are
141	// stricter: any doubled slash (an empty deviceId, sessionId or documentId
142	// segment) or a trailing slash (an empty final id) is a 400 JSON error.
143	func emptyIDGuard(next http.Handler) http.Handler {
144		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
145			p := r.URL.Path
146	
147			documentSegmentEmpty := strings.HasPrefix(p, "/v1/documents//")
148			newFamilySegmentEmpty := false
149			if strings.HasPrefix(p, "/v1/devices/") || strings.HasPrefix(p, "/v1/sessions/") {
150				newFamilySegmentEmpty = strings.Contains(p, "//") || strings.HasSuffix(p, "/")
151			}
152	
153			if documentSegmentEmpty || newFamilySegmentEmpty {
154				writeError(w, http.StatusBadRequest, "path identifiers must be non-empty strings")
155				return
156			}
157			next.ServeHTTP(w, r)
158		})
159	}
