161	// Handler exposes the HTTP surface over a private in-memory store. Use
162	// NewHandler with a durable store for real deployments.
163	func Handler() http.Handler {
164		s, err := store.Open("")
165		if err != nil {
166			log.Fatalf("open in-memory store: %v", err)
167		}
168		return NewHandler(s)
169	}
