171	// decodeJSONBody enforces the strict POST contract shared by every JSON
172	// endpoint: Content-Type must be application/json, the body is capped at
173	// maxBatchBytes, it must contain exactly one JSON value, and no trailing data
174	// may follow it. Any violation writes a 400 JSON error and returns false; the
175	// caller returns immediately, so no handler reaches the store with malformed
176	// input and rejected requests write nothing.
177	func decodeJSONBody(w http.ResponseWriter, r *http.Request, dst any) bool {
178		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
179		if err != nil || mediaType != "application/json" {
180			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
181			return false
182		}
183	
184		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
185		dec := json.NewDecoder(r.Body)
186		if err := dec.Decode(dst); err != nil {
187			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
188			return false
189		}
190		// Reject trailing data after the JSON value.
191		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
192			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
193			return false
194		}
195		return true
196	}
