217	func handleCreateSession(s *store.Store, w http.ResponseWriter, r *http.Request) {
218		deviceID := r.PathValue("deviceId") // route pattern + guard guarantee non-empty
219	
220		var req sessionRequest
221		if !decodeJSONBody(w, r, &req) {
222			return
223		}
224		if req.SessionID == "" {
225			writeError(w, http.StatusBadRequest, "sessionId must be a non-empty string")
226			return
227		}
228	
229		created, err := s.CreateSession(deviceID, req.SessionID)
230		if err != nil {
231			var conflict *store.ErrSessionConflict
232			switch {
233			case errors.Is(err, store.ErrDeviceNotFound):
234				writeError(w, http.StatusNotFound, "device not found")
235			case errors.As(err, &conflict):
236				writeError(w, http.StatusConflict, "sessionId already belongs to another device: "+conflict.ID)
237			default:
238				writeError(w, http.StatusInternalServerError, "failed to create session")
239			}
240			return
241		}
242	
243		writeJSON(w, http.StatusOK, map[string]any{"sessionId": req.SessionID, "created": created})
244	}
