398	func handlePostSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
399		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
400	
401		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
402		if err != nil || mediaType != "application/json" {
403			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
404			return
405		}
406	
407		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
408		var req snapshotPostRequest
409		dec := json.NewDecoder(r.Body)
410		if err := dec.Decode(&req); err != nil {
411			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
412			return
413		}
414		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
415			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
416			return
417		}
418	
419		cursor, ok := parseNonNegativeInt(req.Cursor)
420		if !ok {
421			writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
422			return
423		}
424		if len(req.State) == 0 {
425			writeError(w, http.StatusBadRequest, "state is required")
426			return
427		}
428	
429		created, err := s.PutSnapshot(documentID, cursor, req.State)
430		if err != nil {
431			var conflict *store.ErrSnapshotConflict
432			switch {
433			case errors.Is(err, store.ErrSnapshotBase):
434				writeError(w, http.StatusBadRequest, "document is unknown or cursor is not an existing cursor")
435				return
436			case errors.As(err, &conflict):
437				writeError(w, http.StatusConflict, "snapshot already exists with a different state")
438				return
439			default:
440				writeError(w, http.StatusInternalServerError, "failed to store snapshot")
441				return
442			}
443		}
444	
445		writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "created": created})
446	}
