482		if err := dec.Decode(&req); err != nil {
483			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
484			return
485		}
486		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
487			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
488			return
489		}
490	
491		if req.DeviceID == "" {
492			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
493			return
494		}
495		if req.ChangeID == "" {
496			writeError(w, http.StatusBadRequest, "changeId must be a non-empty string")
497			return
498		}
499		// snapshotCursor must be present and a positive integer (no fractions,
500		// strings, booleans, null or zero).
501		if len(req.SnapshotCursor) == 0 {
502			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
503			return
504		}
505		snapshotCursor, ok := parsePositiveInt(req.SnapshotCursor)
506		if !ok {
507			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
508			return
509		}
510	
511		result, err := s.RestoreSnapshot(documentID, req.DeviceID, req.ChangeID, snapshotCursor)
512		if err != nil {
513			var conflict *store.ErrRestoreConflict
514			switch {
515			case errors.Is(err, store.ErrSnapshotNotFound):
516				writeError(w, http.StatusNotFound, "snapshot not found")
517				return
518			case errors.As(err, &conflict):
519				writeError(w, http.StatusConflict, "change id already exists with a different deviceId, snapshotCursor or source state: "+req.ChangeID)
520				return
521			default:
522				writeError(w, http.StatusInternalServerError, "failed to restore snapshot")
523				return
524			}
525		}
526	
527		writeJSON(w, http.StatusOK, result)
528	}
