530	// parseCursorPath reports whether raw is a decimal non-negative integer and
531	// returns its value. Signs, fractions and other adornments are rejected.
532	func parseCursorPath(raw string) (int64, bool) {
533		if raw == "" {
534			return 0, false
535		}
536		for _, c := range raw {
537			if c < '0' || c > '9' {
538				return 0, false
539			}
540		}
541		n, err := strconv.ParseInt(raw, 10, 64)
542		if err != nil {
543			return 0, false
544		}
545		return n, true
546	}
547	
548	// parseNonNegativeInt reports whether raw is a JSON integer >= 0. Floats,// strings, booleans, null and negative numbers are rejected.
549	func parseNonNegativeInt(raw json.RawMessage) (int64, bool) {
550		var n int64
551		if err := json.Unmarshal(raw, &n); err != nil || n < 0 {
552			return 0, false
553		}
554		// Guard against values like 1.0 that Unmarshal into int64 on some inputs;
555		// require the literal to contain no fraction or exponent.
556		trimmed := strings.TrimSpace(string(raw))
557		if trimmed == "" || trimmed[0] == '-' {
558			return 0, false
559		}
560		for _, c := range trimmed {
561			if c < '0' || c > '9' {
562				return 0, false
563			}
564		}
565		return n, true
566	}
567	
568	// parsePositiveInt reports whether raw is a JSON integer >= 1. Zero, floats,
569	// strings, booleans, null and negative numbers are rejected.
570	func parsePositiveInt(raw json.RawMessage) (int64, bool) {
571		n, ok := parseNonNegativeInt(raw)
572		if !ok || n < 1 {
573			return 0, false
574		}
575		return n, true
576	}
577	
578	// isJSONObject reports whether raw decodes to a JSON object (not null, an
579	// array or a scalar).
580	func isJSONObject(raw json.RawMessage) bool {
581		var m map[string]json.RawMessage
582		if err := json.Unmarshal(raw, &m); err != nil || m == nil {
583			return false
584		}
585		return true
586	}
