588	func handleListChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
589		documentID := r.PathValue("documentID")
590	
591		after, limit, ok := parseChangesQuery(w, r)
592		if !ok {
593			return
594		}
595	
596		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
597		if err != nil {
598			writeError(w, http.StatusInternalServerError, "failed to list changes")
599			return
600		}
601	
602		writeChangesPage(w, changes, nextCursor)
603	}
604	
605	// handleSessionChanges is the session-scoped view of the existing change log:
606	// both path identifiers must be non-empty (the empty-segment guard rejects
607	// those before routing) and the session must currently exist, after which the
608	// query behaves exactly like GET /v1/documents/{documentID}/changes.
609	func handleSessionChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
610		sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
611		documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty
612	
613		// Malformed query parameters are a request-shape error (400) checked
614		// before the resource lookup (404), matching the snapshot GET ordering.
615		after, limit, ok := parseChangesQuery(w, r)
616		if !ok {
617			return
618		}
619	
620		exists, err := s.SessionExists(sessionID)
621		if err != nil {
622			writeError(w, http.StatusInternalServerError, "failed to look up session")
623			return
624		}
625		if !exists {
626			writeError(w, http.StatusNotFound, "session not found")
627			return
628		}
629	
630		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
631		if err != nil {
632			writeError(w, http.StatusInternalServerError, "failed to list changes")
633			return
634		}
635	
636		writeChangesPage(w, changes, nextCursor)
637	}
638	
639	// parseChangesQuery parses the shared after/limit pagination parameters,
640	// writing the documented 400 on an illegal value. It is shared by the
641	// document-scoped and session-scoped change listings so their query semantics
642	// cannot drift apart.
643	func parseChangesQuery(w http.ResponseWriter, r *http.Request) (after, limit int64, ok bool) {
644		q := r.URL.Query()
645	
646		after = 0
647		if raw := q.Get("after"); raw != "" {
648			v, err := strconv.ParseInt(raw, 10, 64)
649			if err != nil || v < 0 {
650				writeError(w, http.StatusBadRequest, "after must be a non-negative integer")
651				return 0, 0, false
652			}
653			after = v
654		}
655	
656		limit = defaultListLimit
657		if raw := q.Get("limit"); raw != "" {
658			v, err := strconv.ParseInt(raw, 10, 64)
659			if err != nil || v < 1 || v > maxListLimit {
660				writeError(w, http.StatusBadRequest, "limit must be an integer between 1 and 1000")
661				return 0, 0, false
662			}
663			limit = v
664		}
665	
666		return after, limit, true
667	}
668	
669	// writeChangesPage renders a change listing page in the shared response shape.
670	func writeChangesPage(w http.ResponseWriter, changes []store.ListedChange, nextCursor int64) {
671		writeJSON(w, http.StatusOK, map[string]any{
672			"changes":    changes,
673			"nextCursor": nextCursor,
674		})
675	}
676	
677	func writeJSON(w http.ResponseWriter, status int, v any) {
678		w.Header().Set("Content-Type", "application/json")
679		w.WriteHeader(status)
680		_ = json.NewEncoder(w).Encode(v)
681	}
682	
683	func writeError(w http.ResponseWriter, status int, message string) {
684		writeJSON(w, status, map[string]string{"error": message})
685	}
686

