		t.Fatalf("create session = %d", w.Code)
	}

	// Seed the document with a change.
	w, _ := postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
		"deviceId": "dev-1",
		"changes":  []any{map[string]any{"id": "c1", "payload": map[string]any{"a": 1}}},
	})
