	w, body = doRequest(t, h, http.MethodGet, "/v1/sessions/sess-2/documents/doc/changes")
	if w.Code != http.StatusOK || body["nextCursor"] != float64(1) {
		t.Fatalf("other device = %d %v", w.Code, body)
